inline const uint8_t* byName(const String& key) {
  if (key == "sunny") return sunny;
  if (key == "clear") return clear;
  if (key == "partlycloudy") return partlycloudy;
  if (key == "cloudy") return cloudy;
  if (key == "fog") return fog;
  if (key == "rain") return rain;
  if (key == "snow") return snow;
  if (key == "sleet") return sleet;
  if (key == "tstorms") return tstorms;
  if (key == "hazy") return hazy;
  if (key == "unknown") return unknown;
  if (key == "nt_clear") return nt_clear;
  if (key == "nt_partlycloudy") return nt_partlycloudy;
  if (key == "nt_cloudy") return nt_cloudy;
  if (key == "nt_fog") return nt_fog;
  if (key == "nt_rain") return nt_rain;
  if (key == "nt_snow") return nt_snow;
  if (key == "nt_sleet") return nt_sleet;
  if (key == "nt_tstorms") return nt_tstorms;
  if (key == "nt_hazy") return nt_hazy;
  if (key == "nt_unknown") return nt_unknown;
  if (key == "nt_sunny") return nt_sunny;
  return unknown;
}

